import data from "./data.json"
import {
  Page,
  Section,
  Group,
  Grid,
  Text,
  Stat,
  DataTable,
  List,
  KV,
  FigureStrip,
  Figure,
  FigureImage,
  FigureLabel,
  FigureText,
} from "@/components/report"

export default function Report() {
  const productRows = data.products.map((p) => ({
    name: p.name,
    steps: p.steps,
    verdict: p.verdict,
  }))

  const issueRows = data.issues.map((i) => ({
    location: `${i.id} · ${i.product} 第 ${i.step} 步`,
    title: i.title,
    severity: i.severity,
    evidence: i.evidence,
  }))

  return (
    <Page title={data.title} meta={["企业网盘", "2026 年 9 月"]}>
      {/* 背景信息 */}
      <Section title="背景信息" description="任务口径与样本规模">
        <KV
          labelCols={2}
          items={[
            { label: "任务", value: data.task },
            { label: "范围", value: data.scope },
            { label: "日期", value: data.date },
          ]}
        />
      </Section>

      {/* 结论 */}
      <Section title="结论" description="本次对比的核心判断">
        <Text className="text-2xl leading-9 font-light">{data.summary}</Text>
      </Section>

      {/* 核心指标 */}
      <Section title="核心指标" description="本次挖掘的样本与结果概览">
        <Grid cols={12} fields={false} className="items-baseline">
          <Stat span={3} captionBelow value={3} unit="个" label="对比产品" />
          <Stat span={3} captionBelow value={12} unit="张" label="分析截图" />
          <Stat
            span={3}
            captionBelow
            size="lg"
            value={3}
            unit="步"
            label="步骤最少(栈盘)"
          />
          <Stat span={3} captionBelow value={3} unit="个" label="发现问题" />
        </Grid>
      </Section>

      {/* 产品对比 */}
      <Section title="产品对比" description="3 款企业网盘,按完成分享的步数对比">
        <DataTable
          columns={[
            { key: "name", label: "产品", span: 2 },
            { key: "steps", label: "步骤数(步)", span: 2, align: "right" },
            { key: "verdict", label: "结论", span: 5 },
          ]}
          rows={productRows}
        />
      </Section>

      {/* 交互链路 */}
      <Section
        title="交互链路"
        description="逐屏拆解从文件到发送的完整流程"
        className="gap-12"
      >
        {data.chains.map((chain) => (
          <Group key={chain.product} title={`${chain.product} · ${chain.version}`}>
            <FigureStrip>
              {chain.steps.map((step) => (
                <Figure key={step.no}>
                  <FigureImage
                    src={step.image}
                    alt={`${chain.product} 第 ${step.no} 步:${step.screen}`}
                  />
                  <FigureLabel>
                    第 {step.no} 步 · {step.screen}
                  </FigureLabel>
                  <FigureText>
                    {step.content} · {step.action}
                    {step.inputs > 0 ? ` · 输入 ${step.inputs} 项` : ""}
                  </FigureText>
                </Figure>
              ))}
            </FigureStrip>
          </Group>
        ))}
      </Section>

      {/* 步骤备注 */}
      <Section title="步骤备注" description="链路各步骤的补充说明">
        <List
          numbered
          columns={2}
          items={data.chains.flatMap((chain) =>
            chain.steps
              .filter((step) => step.note)
              .map((step) => ({
                title: `${chain.product} 第 ${step.no} 步 · ${step.screen}`,
                description: step.note,
              }))
          )}
        />
      </Section>

      {/* 问题 */}
      <Section title="问题" description="共 3 个,集中在云盒的权限与反馈环节">
        <DataTable
          columns={[
            { key: "location", label: "位置", span: 2 },
            { key: "title", label: "问题", span: 3 },
            { key: "severity", label: "严重度", span: 1, levels: ["低", "中", "高"] },
            { key: "evidence", label: "证据", span: 3 },
          ]}
          rows={issueRows}
          caption="严重度按影响范围与用户困惑程度评定"
        />
      </Section>

      {/* 下一步 */}
      <Section title="下一步" description="针对问题的改进方向与依据">
        <List
          columns={3}
          numbered
          items={data.suggestions.map((s) => ({
            title: s.title,
            description: `${s.detail} · 依据:${s.basis.join("、")}`,
          }))}
        />
      </Section>
    </Page>
  )
}

// Report components: the page frame and the content pieces a report is built from.
// Content components draw with render.tsx (the same code the eval-set pages were
// rendered with); the frame components take JSX children.
//
// Frame (swiss): 12 columns of 74px with 24px gutters, 1152px wide. Section titles
// hang in the left 3 columns; section content sits in the right 9.
import * as React from "react"

import { cn } from "@/lib/utils"
import { ScrollArea, ScrollBar } from "@/components/ui/scroll-area"
import { Separator } from "@/components/ui/separator"
import { Node, type SpecNode } from "./render"

const SPAN = ["", "col-span-1", "col-span-2", "col-span-3", "col-span-4", "col-span-5", "col-span-6", "col-span-7", "col-span-8", "col-span-9", "col-span-10", "col-span-11", "col-span-12"]
const COLS: Record<number, string> = { 2: "grid-cols-2", 3: "grid-cols-3", 4: "grid-cols-4", 6: "grid-cols-6", 9: "grid-cols-9", 12: "grid-cols-12" }

type Placed = { span?: number; className?: string }

export function Page({ title, meta = [], className, children }: { title: string; meta?: string[]; className?: string; children: React.ReactNode }) {
  return (
    <main data-slot="page" className={cn("mx-auto flex w-full max-w-6xl flex-col gap-[192px] py-[72px]", className)}>
      <header data-slot="page-header" className="grid h-36 grid-cols-12 content-start items-baseline-last gap-x-6">
        <div className="col-span-3 flex flex-col text-sm leading-6 text-muted-foreground">
          {meta.map((m, i) => <span key={i}>{m}</span>)}
        </div>
        <h1 className="col-span-9 text-5xl leading-[48px] font-medium">{title}</h1>
      </header>
      {children}
    </main>
  )
}

export function Section({ title, description, className, children }: { title: string; description?: string; className?: string; children: React.ReactNode }) {
  return (
    <section data-slot="section" className="grid grid-cols-12 items-start gap-x-6">
      <div data-slot="section-header" className="col-span-3 flex flex-col">
        <h2 className="text-xl leading-6 font-medium">{title}</h2>
        {description && <p className="text-sm leading-6 text-muted-foreground">{description}</p>}
      </div>
      <div data-slot="section-body" className={cn("col-span-9 flex flex-col gap-[192px]", className)}>{children}</div>
    </section>
  )
}

// A group of content, 8px from the title to its content and 24px between the
// content pieces. The group's title is a sub-head: it is set at body size and
// bold, one size step below the section title (14px against the section's
// 20px), so a run of groups reads as separate blocks under their section
// instead of repeating the section heading at its own size.
export function Group({ title, className, children }: { title?: string; className?: string; children: React.ReactNode }) {
  return (
    <div data-slot="group" className="flex flex-col gap-2">
      {title && <h3 data-slot="group-title" className="text-sm leading-6 font-semibold">{title}</h3>}
      <div data-slot="group-body" className={cn("flex flex-col gap-6", className)}>{children}</div>
    </div>
  )
}

// Rows are 144px fields unless fields={false}; a child takes `span` columns (and a Block `rows` fields).
export function Grid({ cols = 9, fields = true, className, children, span }: Placed & { cols?: number; fields?: boolean; children: React.ReactNode }) {
  return (
    <div data-slot="grid" className={cn("grid gap-x-6 gap-y-6", COLS[cols], span && SPAN[span], className)} style={fields ? { gridAutoRows: "144px" } : undefined}>
      {children}
    </div>
  )
}

export function Block({ span, rows, title, description, className, contentClassName, children }: Placed & { rows?: number; title?: string; description?: string; contentClassName?: string; children: React.ReactNode }) {
  return (
    <div data-slot="block" className={cn("flex min-h-0 flex-col", span && SPAN[span], className)} style={rows ? { gridRow: `span ${rows}` } : undefined}>
      {(title || description) && (
        <div data-slot="block-header" className="flex flex-col">
          {title && <h3 className="text-sm leading-6 font-semibold">{title}</h3>}
          {description && <p className="text-sm leading-6 text-muted-foreground">{description}</p>}
        </div>
      )}
      <div data-slot="block-content" className={cn("flex flex-1 flex-col gap-3", contentClassName)}>{children}</div>
    </div>
  )
}

// Content components: props are the fields documented in components.md.
const content = (type: string) =>
  function Content(props: Placed & Record<string, unknown>) {
    return <Node node={{ type, ...props } as SpecNode} ctx={{ span: props.span }} />
  }

export const Stat = content("stat")
export const DataTable = content("table")
export const TrendChart = content("line-chart")
export const BarChart = content("bar-chart")
export const ProgressList = content("progress-list")
export const List = content("list")
export const KV = content("kv")

export function Text({ children, className, span }: Placed & { children: string }) {
  return <Node node={{ type: "text", text: children, className }} ctx={{ span }} />
}

// Screenshots: one screen per Figure, laid out in a FigureStrip that scrolls
// sideways on a shadcn ScrollArea. The strip is what pins the row height: every
// image is drawn at that one height and keeps its own width, so phone
// screenshots and wider analysis screenshots line up in one row without being
// cropped; anything past the right edge is clipped and reached with the
// scrollbar. The scrollbar only appears while the strip is hovered: an
// always-visible bar reads as a rule under the row of screens, which is not a
// line the design gives.
export function FigureStrip({ className, children, ...props }: React.ComponentProps<typeof ScrollArea>) {
  return (
    <ScrollArea data-slot="figure-strip" type="hover" className={cn("w-full min-w-0", className)} {...props}>
      <div
        data-slot="figure-strip-row"
        className={cn(
          "flex w-max gap-12 pb-4",
          "[&_[data-slot=figure-image]]:h-96 [&_[data-slot=figure-image]]:w-auto",
        )}
      >
        {children}
      </div>
      <ScrollBar orientation="horizontal" />
    </ScrollArea>
  )
}

// The screenshots in a comparison set (one interface plus its colour-vision
// simulations) are read side by side, so they take the content width two to a
// row instead of being shrunk to one strip height. Each image fills its cell and
// keeps its ratio, which keeps the text inside the screenshots legible.
export function FigureGrid({ className, children, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="figure-grid"
      className={cn(
        "grid w-full grid-cols-2 gap-x-6 gap-y-6",
        "[&>[data-slot=figure]]:w-full [&>[data-slot=figure]]:min-w-0",
        className
      )}
      {...props}
    >
      {children}
    </div>
  )
}

// The comparison set for colour vision (the interface plus its simulations) has
// to be read as one group: all four views together, at a size where what is
// inside them still reads, and the whole group inside one screen. Four to a row
// is what does that: the content column is wide enough for four views, and one
// band of four is shorter than two bands of two. The earlier two-by-two put two
// views per screen — the second band fell past the fold, so the reader never had
// the four side by side — and the fixed cell height it needed turned a long
// screenshot into a narrow sliver with the band half empty. Here each view takes
// a quarter of the row and keeps its own ratio; the height is capped only so a
// very long screenshot cannot push the group past the screen, and the caption
// runs the width of its cell, so a narrow view does not wrap its label into a
// column of lines.
export function FigureCompare({ className, children, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="figure-compare"
      className={cn(
        "grid w-full grid-cols-4 gap-x-6 gap-y-6",
        "[&>[data-slot=figure]]:w-full [&>[data-slot=figure]]:min-w-0",
        "[&_[data-slot=figure-image]]:h-auto [&_[data-slot=figure-image]]:w-auto [&_[data-slot=figure-image]]:self-start [&_[data-slot=figure-image]]:max-w-full [&_[data-slot=figure-image]]:max-h-96",
        className
      )}
      {...props}
    >
      {children}
    </div>
  )
}

// A group marker: one hairline, the same 1px weight as a table's row lines, with
// an optional label on the line above it. Used where the page groups blocks of
// content (one product per chain-detail group) and the only other rule in sight
// is the table's, so the two read as the same line.
export function Rule({ label, className, ...props }: React.ComponentProps<"div"> & { label?: string }) {
  return (
    <div data-slot="rule" className={cn("flex flex-col gap-2", className)} {...props}>
      {label && <span className="text-xs leading-6 text-muted-foreground">{label}</span>}
      <Separator />
    </div>
  )
}

// As wide as its image: the label and text wrap under it instead of widening (and stretching) the image.
export function Figure({ className, ...props }: React.ComponentProps<"figure">) {
  return <figure data-slot="figure" className={cn("flex w-min shrink-0 flex-col gap-2", className)} {...props} />
}

// The image takes the width its cell gives it and keeps its own ratio: nothing
// is cropped and no height is fixed here. A strip pins the row height (all its
// images share one height, widths differ); a comparison grid lets the column
// width decide, so a view read for its detail is never squeezed down to a strip
// thumbnail.
export function FigureImage({ className, ...props }: React.ComponentProps<"img">) {
  return <img data-slot="figure-image" className={cn("block w-full max-w-none", className)} {...props} />
}

// The screen or view name, on the line the design gives 12px notes.
export function FigureLabel({ className, ...props }: React.ComponentProps<"figcaption">) {
  return <figcaption data-slot="figure-label" className={cn("text-xs leading-6 text-muted-foreground", className)} {...props} />
}

// What happens on the screen (content, action, fields), in body type.
export function FigureText({ className, ...props }: React.ComponentProps<"div">) {
  return <div data-slot="figure-text" className={cn("text-sm leading-6", className)} {...props} />
}

// Renders a UI spec (the generator's output) with the shadcn/ui components.
// Every spec node's outer element carries data-spec="<id>" so that injected
// defects and judge marks can be traced back to the spec.
import * as React from "react"
import { CircleAlert } from "lucide-react"
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  ComposedChart,
  LabelList,
  Line,
  LineChart,
  ReferenceLine,
  XAxis,
  YAxis,
} from "recharts"

import { cn } from "@/lib/utils"
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Badge } from "@/components/ui/badge"
import {
  Card,
  CardAction,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import {
  ChartContainer,
  ChartLegend,
  ChartLegendContent,
  type ChartConfig,
} from "@/components/ui/chart"
import {
  Item,
  ItemActions,
  ItemContent,
  ItemDescription,
  ItemGroup,
  ItemSeparator,
  ItemTitle,
} from "@/components/ui/item"
import { Progress } from "@/components/ui/progress"
import {
  Table,
  TableBody,
  TableCaption,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"

export type SpecNode = {
  id?: string
  type: string
  className?: string
  contentClassName?: string
  span?: number
  src?: string | string[]
  children?: SpecNode[]
  [key: string]: unknown
}

const GRID_COLS: Record<number, string> = { 2: "grid-cols-2", 3: "grid-cols-3", 4: "grid-cols-4", 9: "grid-cols-9", 12: "grid-cols-12" }

// The page frame, chosen by the spec: "swiss" (default) hangs section titles in
// the left 3 of 12 columns; "column" is one 1040px column with section titles
// above their content.
type Frame = "swiss" | "column"
const FrameContext = React.createContext<Frame>("swiss")

// Static strings so Tailwind generates them.
const SPAN = [
  "",
  "col-span-1",
  "col-span-2",
  "col-span-3",
  "col-span-4",
  "col-span-5",
  "col-span-6",
  "col-span-7",
  "col-span-8",
  "col-span-9",
  "col-span-10",
  "col-span-11",
  "col-span-12",
]

// Series colours. A chart on a report page is evidence under a verdict, not the
// page's subject: a palette of four saturated hues made the chart the heaviest
// block on the page and pulled the eye off the conclusion, and it fought the
// page's black-and-grey with one red mark. So a series is drawn in ink, not in
// colour: the first series at full strength and the rest stepping down through
// greys. The order is still readable in greyscale print and to a colour-blind
// reader, the chart's weight stays below the conclusion's, and red is left to
// the verdict alone. The steps are mixed from the page's own tokens, so they
// follow the theme instead of being a second palette beside it.
const SERIES_INK_STEPS = [100, 66, 42, 26]

function seriesInk(i: number) {
  const pct = SERIES_INK_STEPS[i] ?? Math.max(8, 26 - (i - SERIES_INK_STEPS.length + 1) * 6)
  return pct >= 100
    ? "var(--foreground)"
    : `color-mix(in oklab, var(--foreground) ${pct}%, var(--background))`
}

type Ctx = { span?: number; rows?: number }

function mark(node: SpecNode) {
  return { "data-spec": node.id, "data-type": node.type }
}

function outer(node: SpecNode, ctx: Ctx, base?: string) {
  return cn(base, ctx.span ? SPAN[ctx.span] : undefined, node.className)
}

function kids(node: SpecNode) {
  return (node.children ?? []).map((c, i) => <Node key={c.id ?? i} node={c} />)
}

type Series = { key: string; label: string }

function chartConfig(series: Series[]): ChartConfig {
  const cfg: ChartConfig = {}
  series.forEach((s, i) => {
    cfg[s.key] = { label: s.label, color: seriesInk(i) }
  })
  return cfg
}

// The legend lists the series in the order they are drawn, which is the order
// the ink steps down: darkest first. Recharts' default sorter is the data key,
// which shuffles an ordered palette, so the reader would see the greys out of
// order and read the ramp backwards.
function legendOrder(series: Series[]) {
  return (item: { dataKey?: unknown }) => Math.max(0, series.findIndex((s) => s.key === item.dataKey))
}

export function Node({ node, ctx = {} }: { node: SpecNode; ctx?: Ctx }) {
  const p = node as Record<string, any>
  const frame = React.useContext(FrameContext)
  switch (node.type) {
    // Page and section frame (Swiss layout): 12 columns of 74px with 24px
    // gutters on an 8px baseline. Section titles hang in the left 3 columns;
    // content sits in the 9 columns to the right, so the left margin stays a
    // regular, empty field that gives the page its vertical axis.
    case "page":
      if (p.frame === "column")
        return (
          <FrameContext.Provider value="column">
            <main {...mark(node)} data-slot="page" className={outer(node, ctx, "mx-auto flex w-full max-w-[1040px] flex-col gap-[88px] py-[88px]")}>
              <header data-slot="page-header" className="flex flex-col">
                {((p.meta as string[] | undefined) ?? []).length > 0 && (
                  <span className="text-[13px] leading-6 text-muted-foreground">{(p.meta as string[]).join(" · ")}</span>
                )}
                <h1 className="mt-3 text-[44px] leading-[56px] font-semibold">{p.title}</h1>
                {p.lead && <p className="mt-6 max-w-[760px] text-xl leading-[34px] font-light text-foreground/75">{p.lead}</p>}
              </header>
              {kids(node)}
            </main>
          </FrameContext.Provider>
        )
      return (
        // Modular grid: 4 columns of 270px (each divisible into thirds) by fields of
        // 144px (six 24px lines) with a one-line interval. Sections are one empty
        // field apart (24 + 144 + 24 = 192px).
        <main {...mark(node)} data-slot="page" className={outer(node, ctx, "mx-auto flex w-full max-w-6xl flex-col gap-[192px] py-[72px]")}>
          {/* The title takes the 9-column field; the report's facts sit in the
              margin column, their last line on the title's baseline. */}
          <header data-slot="page-header" className="grid h-36 grid-cols-12 content-start items-baseline-last gap-x-6">
            <div className="col-span-3 flex flex-col text-sm leading-6 text-muted-foreground">
              {((p.meta as string[] | undefined) ?? (p.subtitle ? [p.subtitle as string] : [])).map((m, i) => (
                <span key={i}>{m}</span>
              ))}
            </div>
            <h1 className="col-span-9 text-5xl leading-[48px] font-medium">{p.title}</h1>
          </header>
          {kids(node)}
        </main>
      )

    case "section":
      if (frame === "column")
        return (
          <section {...mark(node)} data-slot="section" className={cn("flex flex-col", ctx.span && SPAN[ctx.span])}>
            {/* title on the left, a note (units, period) on the right, a hairline under both */}
            <div data-slot="section-header" className="mb-6 flex items-baseline justify-between gap-6 border-b pb-3">
              <h2 className="text-[22px] leading-8 font-semibold">{p.title}</h2>
              {(p.aside || p.description) && <span className="text-[13px] text-muted-foreground">{p.aside ?? p.description}</span>}
            </div>
            <div data-slot="section-body" className={cn("flex flex-col gap-6", node.className)}>
              {kids(node)}
            </div>
          </section>
        )

    )
  return (
    <section {...mark(node)} data-slot="section" className={cn("grid grid-cols-12 items-start gap-x-6", ctx.span && SPAN[ctx.span])}>
      <div data-slot="section-header" className="col-span-3 flex flex-col">
        <h2 className="text-xl leading-6 font-medium">{p.title}</h2>
        {p.description && <p className="text-sm leading-6 text-muted-foreground">{p.description}</p>}
      </div>
      {/* groups inside a section are one empty field apart, so they stay on field lines */}
      <div data-slot="section-body" className={cn("col-span-9 flex flex-col gap-[192px]", node.className)}>
        {kids(node)}
      </div>
    </section>
  )

case "group":
  return (
    <div {...mark(node)} data-slot="group" className={cn("flex flex-col gap-2", ctx.span && SPAN[ctx.span])}>
      {p.title && <h3 className="text-sm leading-6 font-semibold">{p.title}</h3>}
      <div data-slot="group-body" className={cn("flex flex-col gap-6", node.className)}>
        {kids(node)}
      </div>
    </div>
  )

case "grid":
  return (
    // Fields: rows are 48px with 24px intervals; a child takes `rows` whole fields.
    <div
      {...mark(node)}
      data-slot="grid"
      className={outer(
        node,
        ctx,
        cn(
          "grid gap-x-6 gap-y-6",
          GRID_COLS[(p.cols as number) ?? 12],
          // ruled: a dark rule over the row and hairlines between its cells
          p.ruled && "gap-x-0 border-t border-foreground [&>*]:pt-4 [&>*]:pr-6 [&>*+*]:border-l [&>*+*]:pl-6",
        ),
      )}
      // fields: false lets rows take their content's height instead of whole 144px fields
      style={p.fields === false ? undefined : { gridAutoRows: "144px" }}
    >
      {(node.children ?? []).map((c, i) => (
        <Node key={c.id ?? i} node={c} ctx={{ span: c.span ?? ((p.cols as number) ?? 12), rows: c.rows as number | undefined }} />
      ))}
    </div>
  )

// A titled block without card chrome: 8px from title to content, 16px
// between parts, both below the 24px / 40px between blocks.
case "block":
  return (
    // The block title sits directly on the line above its content, as a bold
    // subhead does in running text: no extra space, so lines stay on the 24px register.
    <div {...mark(node)} data-slot="block" className={outer(node, ctx, "flex min-h-0 flex-col")} style={ctx.rows ? { gridRow: `span ${ctx.rows}` } : undefined}>
      {(p.title || p.description) && (
        <div data-slot="block-header" className="flex flex-col">
          {p.title && <h3 className="text-sm leading-6 font-semibold">{p.title}</h3>}
          {p.description && <p className="text-sm leading-6 text-muted-foreground">{p.description}</p>}
        </div>
      )}
      {/* flex-1: a block stretched by its grid row passes the height on, so
          elastic content (charts, distributed lists) can fill the band. */}
      <div data-slot="block-content" className={cn("flex flex-1 flex-col gap-3", node.contentClassName as string)}>
        {kids(node)}
      </div>
    </div>
  )

case "card":
  return (
    <Card {...mark(node)} className={outer(node, ctx)}>
      {(p.title || p.description || p.badge) && (
        <CardHeader>
          {p.title && <CardTitle>{p.title}</CardTitle>}
          {p.description && <CardDescription>{p.description}</CardDescription>}
          {p.badge && (
            <CardAction>
              <Badge variant="outline">{p.badge}</Badge>
            </CardAction>
          )}
        </CardHeader>
      )}
      <CardContent className={cn("flex flex-col gap-6", node.contentClassName as string)}>
        {kids(node)}
      </CardContent>
      {p.footer && (
        <CardFooter className="text-sm text-muted-foreground">{p.footer}</CardFooter>
      )}
    </Card>
  )

case "stat": {
  const dir = p.direction as "up" | "down" | undefined
  return (
    <div {...mark(node)} data-slot="custom-stat" className={outer(node, ctx, cn("flex flex-col", p.captionBelow ? "gap-0" : "gap-2"))}>
      {/* captionBelow: the number comes first, so a row of figures can align on their baselines */}
      {p.label && !p.captionBelow && <span className="text-sm leading-6 text-muted-foreground">{p.label}</span>}
      <div className="flex items-baseline gap-2">
        <span className={cn("font-light tabular-nums", p.size === "lg" ? "text-5xl leading-[60px]" : p.size === "xl" ? "text-[44px] leading-[56px]" : "text-3xl leading-9")}>{p.value}</span>
        {p.unit && <span className="text-sm text-muted-foreground">{p.unit}</span>}
      </div>
      {p.label && p.captionBelow && <span className={p.quiet ? "text-xs leading-6 text-muted-foreground" : "text-sm leading-6"}>{p.label}</span>}
      {(p.delta || p.note) && (
        <div className="flex items-center gap-2">
          {p.delta && (
            <Badge variant="outline" className={dir === "down" ? "text-destructive" : undefined}>
              {p.delta}
            </Badge>
          )}
          {/* without a delta badge the note carries the change, so a fall is drawn in the destructive colour */}
          {p.note && <span className={cn("text-xs leading-6", !p.delta && dir === "down" ? "text-destructive" : "text-muted-foreground")}>{p.note}</span>}
        </div>
      )}
    </div>
  )
}

case "text":
  return (
    <p {...mark(node)} data-slot="text" className={outer(node, ctx, "text-sm leading-6")}>
      {p.text}
    </p>
  )

case "table": {
  // span: the column's width in grid columns, so cell text starts on a column line.
  // tone: values listed here are drawn in the destructive colour (a state, e.g. 严重)
  // and two weights heavier than the body. Red on its own is a lighter grey than
  // black in greyscale printing and is invisible to a colour-blind reader, so the
  // state has to carry a second, non-colour channel: the weight.
  // interval: the cell draws the row's estimate (key) with its range (low..high) on an axis shared by the column.
  // muteWhen: the cell is greyed when the row's field equals the value (e.g. not significant).
  type Col = {
    key: string; label: string; align?: "left" | "right"; bar?: boolean; span?: number; tone?: string[]; levels?: string[]
    interval?: { low: string; high: string; domain: [number, number] }
    muteWhen?: { key: string; equals: unknown }
  }
  const cols = p.columns as Col[]
  const onGrid = cols.some((c) => c.span)
  const rows = p.rows as Record<string, React.ReactNode>[]
  // levels: a column whose values are one ordered scale (low to high). The
  // top of the scale carries the destructive colour; the step below it is
  // bold; the steps under that fall back to the note grey. Colour alone
  // would only mark one state, so the weight and the grey carry the rest of
  // the order and the reader can rank the values.
  const step = (c: Col, v: React.ReactNode) => {
    const i = c.levels ? c.levels.indexOf(String(v)) : -1
    if (i < 0) return undefined
    const fromTop = c.levels!.length - 1 - i
    return fromTop === 0 ? "font-semibold text-destructive" : fromTop === 1 ? "font-semibold" : "text-muted-foreground"
  }
  // A numeric column can carry an inline bar, scaled to the column's max.
  const max = Object.fromEntries(cols.filter((c) => c.bar).map((c) => [c.key, Math.max(...rows.map((r) => Number(r[c.key]) || 0))]))
  const interval = (c: Col, r: Record<string, React.ReactNode>, muted: boolean) => {
    const [lo, hi] = c.interval!.domain
    const x = (v: unknown) => ((Number(v) - lo) / (hi - lo)) * 100
    const ink = muted ? "var(--muted-foreground)" : "var(--foreground)"
    return (
      <svg width="100%" height="16" className="block overflow-visible" aria-label={`${r[c.key]} [${r[c.interval!.low]}, ${r[c.interval!.high]}]`}>
        <line x1={`${x(0)}%`} x2={`${x(0)}%`} y1="-12" y2="28" stroke="var(--border)" />
        <line x1={`${x(r[c.interval!.low])}%`} x2={`${x(r[c.interval!.high])}%`} y1="8" y2="8" stroke={ink} strokeOpacity={muted ? 0.5 : 1} strokeWidth="1.5" />
        <circle cx={`${x(r[c.key])}%`} cy="8" r="3.5" fill={ink} fillOpacity={muted ? 0.5 : 1} />
      </svg>
    )
  }
  const cell = (c: Col, v: React.ReactNode, r: Record<string, React.ReactNode>, muted: boolean) =>
    c.interval ? (
      interval(c, r, muted)
    ) : c.bar ? (
      <div className="flex items-center gap-3">
        <span className="w-8 tabular-nums">{v}</span>
        {/* the count is drawn as a two-pixel bar on a hairline baseline, so
            the length against that baseline is the difference the eye reads
            (a hairline on a hairline made every row look the same) */}
        <Progress value={((Number(v) || 0) / max[c.key]) * 100} className="flex-1" />
      </div>
    ) : (
      v
    )
  return (
    <div {...mark(node)} data-slot="custom-table" className={outer(node, ctx)}>
      <Table className={onGrid ? "table-fixed" : undefined}>
        {onGrid && (
          <colgroup>
            {cols.map((c, i) => (
              // n columns plus the gutter after them; the last column has no gutter
              <col key={c.key} style={{ width: (c.span ?? 1) * 98 - (i === cols.length - 1 ? 24 : 0) }} />
            ))}
          </colgroup>
        )}
        {p.caption && <TableCaption>{p.caption}</TableCaption>}
        <TableHeader>
          <TableRow>
            {cols.map((c, i) => (
              <TableHead key={c.key} className={cn(c.align === "right" && "text-right", onGrid && "h-[39px] pl-0 pr-6 text-muted-foreground font-normal", onGrid && i === cols.length - 1 && "pr-0")}>
                {c.label}
              </TableHead>
            ))}
          </TableRow>
        </TableHeader>
        <TableBody>
          {rows.map((r, i) => (
            <TableRow key={i}>
              {cols.map((c, i) => (
                <TableCell
                  key={c.key}
                  className={cn(
                    c.align === "right" && "text-right tabular-nums",
                    // 39px + the 1px row rule = a 40px row
                    onGrid && "h-[39px] py-0 pl-0 pr-6 whitespace-normal",
                    onGrid && i === cols.length - 1 && "pr-0",
                    // the state carries weight as well as colour: bolder than the body
                    // text, so it survives greyscale and colour blindness
                    c.tone?.includes(String(r[c.key])) && "font-semibold text-destructive",
                    step(c, r[c.key]),
                    c.muteWhen && r[c.muteWhen.key] === c.muteWhen.equals && "text-muted-foreground/70",
                  )}
                >
                  {cell(c, r[c.key], r, !!c.muteWhen && r[c.muteWhen.key] === c.muteWhen.equals)}
                </TableCell>
              ))}
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  )
}

case "bar-chart":
case "line-chart": {
  const series = p.series as Series[]
  const cfg = chartConfig(series)
  // height "fill": the chart takes whatever height its block is given.
  const fill = p.height === "fill"
  const height = fill ? "flex-1 min-h-24" : ((p.height as string) ?? "h-60")
  const horizontal = p.layout === "horizontal"
  const data = p.data as Record<string, unknown>[]
  // Line charts: y range rounded out to tens, one tick every 10.
  const vals = data.flatMap((r) => series.map((x) => Number(r[x.key]))).filter((v) => !Number.isNaN(v))
  const yLo = Math.floor((Math.min(...vals) - 1) / 10) * 10
  const yHi = Math.ceil((Math.max(...vals) + 1) / 10) * 10
  const yTicks = Array.from({ length: (yHi - yLo) / 10 + 1 }, (_, i) => yLo + i * 10)
  // Horizontal bars read like a ranked list: category, a thin bar in the
  // same ink as the progress bars, the value at its end. No grid or value
  // axis; the height follows the number of bars.
  if (node.type === "bar-chart" && horizontal && series.length === 1) {
    const key = series[0].key
    return (
      <div {...mark(node)} data-slot="custom-chart" className={outer(node, ctx)}>
        <ChartContainer config={cfg} className="aspect-auto w-full" style={{ height: data.length * 30 }}>
          <BarChart data={data} layout="vertical" margin={{ left: 0, right: 40, top: 0, bottom: 0 }} barCategoryGap={0}>
            <XAxis type="number" hide domain={[0, "dataMax"]} />
            <YAxis type="category" dataKey={p.xKey} tickLine={false} axisLine={false} width={64} tick={{ fill: "var(--foreground)", fontSize: 13 }} />
            <Bar dataKey={key} fill="var(--primary)" barSize={10} radius={[0, 5, 5, 0]} isAnimationActive={false}>
              <LabelList dataKey={key} position="right" offset={10} className="fill-muted-foreground" fontSize={12} />
            </Bar>
          </BarChart>
        </ChartContainer>
      </div>
    )
  }
  // One series drawn as a quiet trend: optional y ticks with a grid, a
  // shaded range (band), a zero line, sparse x labels and only the last
  // point labelled.
  if (node.type === "line-chart" && series.length === 1 && (p.band || p.yTicks || p.pointLabels === "last")) {
    const key = series[0].key
    const ticks = p.yTicks as number[] | undefined
    const band = p.band as { low: string; high: string } | undefined

        const band = p.band as { low: string; high: string } | undefined
        const rows = band ? data.map((r) => ({ ...r, __band: [r[band.low], r[band.high]] })) : data
        const n = data.length
        return (
          <div {...mark(node)} data-slot="custom-chart" className={outer(node, ctx, fill ? "flex min-h-0 flex-1 flex-col" : undefined)}>
            <ChartContainer config={cfg} className={cn("aspect-auto w-full", height)}>
              <ComposedChart data={rows} margin={{ left: 0, right: 24, top: 24, bottom: 0 }}>
                {ticks && <CartesianGrid vertical={false} strokeOpacity={0.5} />}
                <XAxis dataKey={p.xKey} tickLine={false} axisLine={false} tickMargin={12} fontSize={12} interval={(p.xInterval as number | undefined) ?? "preserveStartEnd"} />
                <YAxis hide={!ticks} domain={ticks ? [ticks[0], ticks[ticks.length - 1]] : ["auto", "auto"]} ticks={ticks} interval={0} tickLine={false} axisLine={false} width={32} fontSize={12} />
                {band && <Area dataKey="__band" stroke="none" fill="var(--foreground)" fillOpacity={0.06} isAnimationActive={false} />}
                {p.zero && <ReferenceLine y={0} stroke="var(--muted-foreground)" strokeOpacity={0.5} />}
                <Line dataKey={key} stroke="var(--foreground)" strokeWidth={1.5} dot={false} isAnimationActive={false}>
                  <LabelList
                    dataKey={key}
                    content={(lp: any) =>
                      lp.index === n - 1 ? (
                        <g>
                          <circle cx={lp.x} cy={lp.y} r={3} fill="var(--foreground)" />
                          <text x={lp.x - 6} y={lp.y - 10} textAnchor="end" fontSize={12} fontWeight={500} fill="var(--foreground)">
                            {(p.lastLabel as string | undefined) ?? lp.value}
                          </text>
                        </g>
                      ) : null
                    }
                  />
                </Line>
              </ComposedChart>
            </ChartContainer>
          </div>
        )
      }
      return (
        <div {...mark(node)} data-slot="custom-chart" className={outer(node, ctx, fill ? "flex min-h-0 flex-1 flex-col" : undefined)}>
          <ChartContainer config={cfg} className={cn("aspect-auto w-full", height)}>
            {node.type === "bar-chart" ? (
              <BarChart
                data={p.data}
                layout={horizontal ? "vertical" : "horizontal"}
                margin={{ left: 0, right: 8, top: 8, bottom: 0 }}
              >
                <CartesianGrid vertical={horizontal} horizontal={!horizontal} />
                {horizontal ? (
                  <>
                    <XAxis type="number" tickLine={false} axisLine={false} />
                    <YAxis type="category" dataKey={p.xKey} tickLine={false} axisLine={false} width={72} />
                  </>
                ) : (
                  <>
                    <XAxis dataKey={p.xKey} tickLine={false} axisLine={false} tickMargin={8} />
                    <YAxis tickLine={false} axisLine={false} width={40} />
                  </>
                )}
                {series.length > 1 && <ChartLegend content={<ChartLegendContent />} itemSorter={legendOrder(series)} />}
                {series.map((s) => (
                  <Bar key={s.key} dataKey={s.key} fill={`var(--color-${s.key})`} radius={4} isAnimationActive={false} />
                ))}
              </BarChart>
            ) : (
              series.length === 1 ? (
                // One series: no axes or grid; each point carries its value, so
                // the line is read directly (and the values are in the DOM).
                <LineChart data={p.data} margin={{ left: 16, right: 16, top: 24, bottom: 0 }}>
                  <XAxis dataKey={p.xKey} tickLine={false} axisLine={false} tickMargin={12} fontSize={12} interval={0} padding={{ left: 8, right: 8 }} />
                  <YAxis hide domain={[yTicks[0], yTicks[yTicks.length - 1]]} />
                  <Line dataKey={series[0].key} stroke="var(--primary)" strokeWidth={1.5} dot={{ r: 2.5, fill: "var(--primary)", strokeWidth: 0 }} isAnimationActive={false}>
                    <LabelList dataKey={series[0].key} position="top" offset={10} fontSize={12} className="fill-foreground" />
                  </Line>
                </LineChart>
              ) : (
              <LineChart data={p.data} margin={{ left: 0, right: 16, top: 8, bottom: 0 }}>
                <CartesianGrid vertical={false} strokeOpacity={0.6} />
                <XAxis dataKey={p.xKey} tickLine={false} axisLine={false} tickMargin={8} fontSize={12} />
                {/* a trend reads by its slope, so the axis fits the data range instead of starting at 0 */}
                <YAxis tickLine={false} axisLine={false} width={32} fontSize={12} domain={[yTicks[0], yTicks[yTicks.length - 1]]} ticks={yTicks} interval={0} />
                {series.length > 1 && <ChartLegend content={<ChartLegendContent />} itemSorter={legendOrder(series)} />}
                {series.map((s) => (
                  <Line key={s.key} dataKey={s.key} stroke={series.length > 1 ? `var(--color-${s.key})` : "var(--primary)"} strokeWidth={2} dot={{ r: 3, fill: "var(--background)", strokeWidth: 2 }} isAnimationActive={false} />
                ))}
              </LineChart>
              )
            )}
          </ChartContainer>
        </div>
      )
    }

    case "progress-list": {
      // Every bar in the list is read against one scale, so the lengths are
      // comparable inside the list: the scale runs from zero to the largest
      // count in the list unless an item names its own max. (Falling back to a
      // fixed 0..100 left every count a sliver of the same length, which reads
      // as a dashed rule rather than as a value.)
      const items = p.items as { label: string; value: number; max?: number; display?: string }[]
      const scale = Math.max(1, ...items.map((it) => Number(it.value) || 0))
      const bar = (it: { value: number; max?: number }) => ((Number(it.value) || 0) / (it.max ?? scale)) * 100
      // compact: one line per item (label, bar, value). The label column is one grid
      // column (74px) plus the gutter (24px), so the bar starts on the same column
      // line as the table next to it instead of on a line of its own. The bar is
      // read against its baseline, and the value is tabular so the counts line up.
      if (p.compact)
        return (
          <div {...mark(node)} data-slot="custom-progress-list" className={outer(node, ctx, "flex flex-col gap-2")}>
            {items.map((it, i) => (
              <div key={i} className="grid h-6 grid-cols-[74px_1fr_2rem] items-center gap-6 text-sm">
                <span>{it.label}</span>
                <Progress value={bar(it)} />
                <span className="text-right tabular-nums">{it.display ?? it.value}</span>
              </div>
            ))}
          </div>
        )
      return (
        <div {...mark(node)} data-slot="custom-progress-list" className={outer(node, ctx, "flex flex-col gap-4")}>
          {items.map((it, i) => (
            <div key={i} className="flex flex-col gap-2">
              <div className="flex items-center justify-between text-sm">
                <span>{it.label}</span>
                {/* the count is the row's data, so it is set like every other
                    number on the page (same colour, tabular figures) instead of
                    dropping to the note grey */}
                <span className="tabular-nums">{it.display ?? it.value}</span>
              </div>
              <Progress value={bar(it)} />
            </div>
          ))}
        </div>
      )
    }

    case "badges":
      return (
        <div {...mark(node)} data-slot="custom-badges" className={outer(node, ctx, "flex flex-wrap gap-2")}>
          {(p.items as string[]).map((t, i) => (
            <Badge key={i} variant="secondary">
              {t}
            </Badge>
          ))}
        </div>
      )

    case "list": {
      const items = p.items as { title?: string; description?: string; meta?: string }[]
      // numbered: "01", "02" … instead of 1, 2; columns: the items sit side by
      // side, each with its number (or its meta) as a small line above.
      const num = (i: number) => String(i + 1).padStart(2, "0")
      if (p.columns)
        return (
          <div {...mark(node)} data-slot="custom-list" className={outer(node, ctx, cn("grid gap-x-6 gap-y-6", GRID_COLS[p.columns as number]))}>
            {items.map((it, i) => (
              <div key={i} className="flex flex-col text-sm leading-6">
                {(p.numbered || it.meta) && (
                  <span className={cn("text-xs leading-6", it.meta && p.metaTone === "destructive" ? "text-destructive" : "text-muted-foreground")}>
                    {it.meta ?? num(i)}
                  </span>
                )}
                {it.title && <span className="font-semibold">{it.title}</span>}
                {it.description && <span className="text-foreground/70">{it.description}</span>}
              </div>
            ))}
          </div>
        )
      if (p.numbered)
        return (
          <ol {...mark(node)} data-slot="custom-list" className={outer(node, ctx, "flex flex-col")}>
            {items.map((it, i) => (
              <li key={i} className="grid grid-cols-[48px_1fr] border-b py-5 text-sm leading-6">
                <span className="text-xs leading-6 text-muted-foreground tabular-nums">{num(i)}</span>
                <div className="flex flex-col">
                  {it.title && <span className="font-semibold">{it.title}</span>}
                  {it.description && <span className="text-foreground/70">{it.description}</span>}
                </div>
              </li>
            ))}
          </ol>
        )
      return (
        // Undivided lists: an item's title and description sit tight (two 24px lines),
        // with a 12px gap only between items.
        <ItemGroup {...mark(node)} className={outer(node, ctx, p.divided === false ? "gap-3" : undefined)}>
          {items.map((it, i) => (
            <React.Fragment key={i}>
              {i > 0 && p.divided !== false && <ItemSeparator />}
              <Item size="sm" className={cn(p.divided === false ? "border-0 p-0" : "px-0", p.ordered && "items-start gap-0")}>
                {/* ordered: the items are a sequence (e.g. priority), so they carry their number */}
                {p.ordered && <span className="w-6 shrink-0 text-sm leading-6 font-medium tabular-nums">{i + 1}</span>}
                <ItemContent className={p.divided === false ? "gap-0" : undefined}>
                  <ItemTitle className={p.divided === false ? "leading-6" : undefined}>{it.title}</ItemTitle>
                  {it.description && <ItemDescription className={p.divided === false ? "leading-6" : undefined}>{it.description}</ItemDescription>}
                </ItemContent>
                {it.meta && (
                  <ItemActions>
                    <Badge variant="outline">{it.meta}</Badge>
                  </ItemActions>
                )}
              </Item>
            </React.Fragment>
          ))}
        </ItemGroup>
      )
    }

    case "alert":
      return (
        <Alert {...mark(node)} variant={p.variant ?? "default"} className={outer(node, ctx)}>
          <CircleAlert />
          <AlertTitle>{p.title}</AlertTitle>
          {p.text && <AlertDescription>{p.text}</AlertDescription>}
        </Alert>
      )

    case "kv":
      return (
        // labelCols: the label takes n grid columns and the value starts on the next column line.
        <dl
          {...mark(node)}
          data-slot="custom-kv"
          className={outer(node, ctx, cn("grid text-sm leading-6", p.labelCols ? "gap-x-6 gap-y-0" : "grid-cols-2 gap-x-4 gap-y-3"))}
          style={p.labelCols ? { gridTemplateColumns: `${(p.labelCols as number) * 98 - 24}px 1fr` } : undefined}
        >
          {(p.items as { label: string; value: string }[]).map((it, i) => (
            <React.Fragment key={i}>
              <dt className="text-muted-foreground">{it.label}</dt>
              <dd className={cn("tabular-nums", p.labelCols ? "text-left" : "text-right font-medium")}>{it.value}</dd>
            </React.Fragment>
          ))}
        </dl>
      )

    default:
      return (
        <div {...mark(node)} data-slot="unknown" className="text-destructive">
          unknown node type: {node.type}
        </div>
      )
  }
}
